"""Embed the original WildStar LandWater D3D9 shader bytecode in the client."""
from pathlib import Path
import hashlib
import sys

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "tools"))
from sho_reader import read_sho

sources = [
    ("Vertex", "LandWaterVS.vs_3_0.sho", 0),
    ("Pixel", "LandWaterPS.ps_3_0.sho", 0),
]
parts = [
    "// Generated by tools/build_ws_water_shader.py from the original WildStar SHO containers.\n",
    "#pragma once\n#include <cstdint>\nnamespace WildStarWaterBytecode {\n",
]
for symbol, name, index in sources:
    path = ROOT / "WoWClient/ClientData/Shaders" / name
    data = path.read_bytes()
    container = read_sho(data)
    blob = container["code"][index]
    code = data[blob["offset"]:blob["offset"] + blob["bytes"]]
    parts[0] = parts[0].replace("containers.", f"containers; {name} SHA256 {hashlib.sha256(data).hexdigest()}.")
    parts.append(f"inline constexpr uint8_t {symbol}[] = {{\n")
    for offset in range(0, len(code), 24):
        parts.append("    " + ",".join(f"0x{x:02x}" for x in code[offset:offset + 24]) + ",\n")
    parts.append("};\n")
# Compile only the forward-output adapter; the original VS and PS above stay embedded.
import ctypes
import importlib.util
spec = importlib.util.spec_from_file_location("sky_shader_compiler", ROOT / "tools/build_sky_shaders.py")
compiler = importlib.util.module_from_spec(spec)
spec.loader.exec_module(compiler)
source_path = ROOT / "wowdecomp/WoW/Source/LiquidSystem/Shaders/WildStarWaterForward.hlsl"
compiler.SOURCE = source_path
code = compiler.compile_shader(source_path.read_bytes(), "ps_3_0")
parts.append("inline constexpr uint8_t PixelForward[] = {\n")
for offset in range(0, len(code), 24):
    parts.append("    " + ",".join(f"0x{x:02x}" for x in code[offset:offset + 24]) + ",\n")
parts.append("};\n")
parts.append("}  // namespace WildStarWaterBytecode\n")
out = ROOT / "wowdecomp/WoW/Source/LiquidSystem/WildStarWaterBytecode.h"
out.write_text("".join(parts), encoding="utf-8")
print(out)
